// Conexoes vem de PLUGGY_ITEM_IDS, no ambiente do n8n (mesmo formato do .env do Ember):
// "banco_a:<itemId>,banco_b:<itemId>". Conectar pelo MeuPluggy: esses itemIds nao expiram.
// GET /items sem id nao lista (nao e rota de listagem), por isso a lista vem da configuracao.
// O n8n precisa deixar o Code node ler o ambiente (N8N_BLOCK_ENV_ACCESS_IN_NODE=false).
const apiKey = $input.first().json.apiKey;
const bruto = $env.PLUGGY_ITEM_IDS;
if (!bruto) throw new Error('Falta PLUGGY_ITEM_IDS no ambiente do n8n (ex.: banco_a:<itemId>,banco_b:<itemId>)');
const FONTE = /^[a-z0-9_]{1,30}$/;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const itens = bruto.split(',').map((p) => p.trim()).filter(Boolean).map((p) => {
  const i = p.indexOf(':');
  const fonte = p.slice(0, i).trim();
  const itemId = p.slice(i + 1).trim().toLowerCase();
  if (i < 0 || !FONTE.test(fonte) || !UUID.test(itemId)) {
    throw new Error('PLUGGY_ITEM_IDS invalido: use fonte:itemId separados por virgula');
  }
  return { fonte, itemId };
});
return itens.map((it) => ({ json: { ...it, apiKey } }));

// Pagina /v2/transactions por cursor (campo 'next', nao 'page'/'pageSize').
// GET /transactions foi descontinuado em favor deste.
// 'next' e a query string INTEIRA da proxima pagina ('?accountId=...&after=...'),
// nao um token solto: usar direto, nunca montar '&cursor=' por cima.
// Janela: ultimos 15 dias, upsert acontece no proximo node via hash_dedup.
const crypto = require('crypto');
const apiKey = $json.apiKey;
const contaId = $json.id;
const fonte = $json.fonte;

const quinzeDiasAtras = new Date(Date.now() - 15 * 24 * 60 * 60 * 1000)
  .toISOString()
  .slice(0, 10);

let url = `https://api.pluggy.ai/v2/transactions?accountId=${contaId}`;
const todas = [];

while (url) {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url,
    headers: { 'X-API-KEY': apiKey },
    json: true,
  });
  todas.push(...resp.results);
  url = resp.next ? `https://api.pluggy.ai/v2/transactions${resp.next}` : null;
}

const recentes = todas.filter((t) => (t.date || '').slice(0, 10) >= quinzeDiasAtras);

// Transacoes identicas no mesmo dia (dois Pix de R$230 pro mesmo destino) tem IDs
// diferentes na Pluggy mas o mesmo hash. Sem desempate elas se fundem no upsert
// O ordinal conta a ocorrencia dentro do grupo, na ordem que a API devolve.
// Premissa: a ordem da API e estavel entre rodadas.
const vistos = new Map();

return recentes.map((t) => {
  const parcela = t.creditCardMetadata ? t.creditCardMetadata.installmentNumber : null;
  const descricaoRaw = t.descriptionRaw || '';
  const dataStr = (t.date || '').slice(0, 10);
  const base = [contaId, dataStr, String(t.amount), descricaoRaw, parcela != null ? String(parcela) : '0'].join('|');
  const ordinal = vistos.get(base) || 0;
  vistos.set(base, ordinal + 1);
  const hashDedup = crypto.createHash('md5').update(base + '|' + ordinal).digest('hex');

  return {
    json: {
      hash_dedup: hashDedup,
      pluggy_transaction_id: t.id,
      data: dataStr,
      data_competencia: dataStr,
      valor: t.amount,
      descricao_raw: descricaoRaw,
      descricao: t.description || null,
      fonte,
      tipo_movimento: t.creditCardMetadata ? 'cartao_credito' : 'conta',
      conta_id: contaId,
      parcela_atual: parcela,
      parcela_total: t.creditCardMetadata ? t.creditCardMetadata.totalInstallments : null,
      bill_id: t.creditCardMetadata ? t.creditCardMetadata.billId : null,
      payload: t,
    },
  };
});
